    pub const Deflate = libraries.lvo(8);
    pub const EndDeflate = libraries.lvo(9);
    pub const Uncompress = libraries.lvo(10);
    pub const Compress = libraries.lvo(11);
    pub const CompressBound = libraries.lvo(12);
    pub const Crc32 = libraries.lvo(13);
    pub const Adler32 = libraries.lvo(14);
};

/// Each function's type, by its name in LVO. The first argument is the
