pub const Fn = struct {
    pub const InitInflate = *const fn (*CompressionBase, *compression.Stream, u32) callconv(.c) i32;
    pub const Inflate = *const fn (*CompressionBase, *compression.Stream, u32) callconv(.c) i32;
    pub const EndInflate = *const fn (*CompressionBase, *compression.Stream) callconv(.c) void;
    pub const InitDeflate = *const fn (*CompressionBase, *compression.Stream, u32, u32) callconv(.c) i32;
    pub const Deflate = *const fn (*CompressionBase, *compression.Stream, u32) callconv(.c) i32;
    pub const EndDeflate = *const fn (*CompressionBase, *compression.Stream) callconv(.c) void;
    pub const Uncompress = *const fn (*CompressionBase, *compression.Stream, u32) callconv(.c) i32;
    pub const Compress = *const fn (*CompressionBase, *compression.Stream, u32, u32) callconv(.c) i32;
    pub const CompressBound = *const fn (*CompressionBase, u32, u32) callconv(.c) u32;
    pub const Crc32 = *const fn (*CompressionBase, u32, ?*const anyopaque, u32) callconv(.c) u32;
    pub const Adler32 = *const fn (*CompressionBase, u32, ?*const anyopaque, u32) callconv(.c) u32;
};

